    private aggregationMethodToQueryLine(aggMethod: aggregationMethod) {
        switch (aggMethod) {
            case 'sum':
                return 'sum';
            case 'average':
                return 'mean';
            case 'min':
                return 'min';
            case 'max':
                return 'max';
            case 'count':
                return 'count';
        }
    }
    private aggregationIntervalToInfluxQueryLine(aggregationInterval: aggregationInterval) {
        switch (aggregationInterval) {
            case 'hour':
                return '1h';
            case 'day':
                return '1d';
        }
    }
