                body: JSON.stringify({
                    timeStamp: timestamp,
                    applicationId,
                    serviceId,
                    dimensionId,
                    recordValue,
                    metadata,
                }),
            });
            if (res.status <= 201) {
                return await res.json();
            } else if (retries === MAX_RETRY - 1) {
                throw new Error(JSON.stringify(await res.json(), null, 2));
            } else {
                await sleep(1000 * (retries + 1));
            }
        }
    }
}

