import { Module, forwardRef } from '@nestjs/common';
import { CustomerService } from './customer.service';
import { PrivateAPICustomerController, PublicAPICustomerController } from './customer.controller';
import { InfluxModule } from '../influx/influx.module';
import { SchedulerModule } from '../scheduler/scheduler.module';
import { PublicAPIOfferingModule } from '../offering/offering.module';
import { UsageModule } from '../usage/usage.module';
import { CustomerIdExistsRule } from './dto/customerIdExists';

@Module({
    controllers: [PublicAPICustomerController],
    providers: [CustomerService, CustomerIdExistsRule],
    imports: [
        InfluxModule,
        forwardRef(() => SchedulerModule),
        forwardRef(() => PublicAPIOfferingModule),
        forwardRef(() => UsageModule),
    ],
    exports: [CustomerService],
})
export class PublicAPICustomerModule {}

@Module({
    controllers: [PrivateAPICustomerController],
})
export class PrivateAPICustomerModule extends PublicAPICustomerModule {}

import { Injectable, Optional } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CustomerService } from '../customer.service';

@ValidatorConstraint({ name: 'CustomerIdExistsRule', async: true })
@Injectable()
export class CustomerIdExistsRule implements ValidatorConstraintInterface {
    constructor(@Optional() readonly customerService?: CustomerService) {}

    async validate(id: string, args: ValidationArguments) {
        if (!id) {
            return true;
        }
        if (!this.customerService?.findOne) {
            // Without a resolved customer service the existence of the customer cannot be verified
            return true;
        }
        try {
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            await this.customerService.findOne({ customerId: id, businessID: args?.object?.businessID });
            return true;
        } catch (e) {
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        return `customerId: ${args.object?.customerId} doesn't exist`;
    }
}

export function CustomerIdExists(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'customerIdExists',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: CustomerIdExistsRule,
        });
    };
}

