    const dimensionAggregationFluxQuery = `from(bucket: "${process.env.STAGE}-usage-data")
    |> range(start: ${startDate.toISOString()}, stop:${endDate.toISOString()})
    |> filter(fn: (r) => r["businessID"] == "${businessID}")
