/**
 * Gathers the usage of every dimension attached to the offering of a customer.
 * The customer is the ownership boundary of usage, every query is aggregated with its customerId.
 */
async findUsageForCustomer(
    { customerId, businessID, offering }: ReadUsageForCustomerDto,
    overrides: QueryParamUsageDto
): Promise<AggregatedUsageResponse[] | UnAggregatedUsageResponse[]> {
    const offeringDoc = offering ? offering : await this.findOfferingForCustomer({ customerId, businessID });
    if (!offeringDoc) {
        throw new ConflictException(
            `Customer with ID: ${customerId} has no offering attached, attach an offering to the customer before reading usage`
        );
    }
    const { dimensions, ...restOfOfferingDoc } = offeringDoc;
    let setDimensions = dimensions;
    if (overrides?.aggregationInterval) {
        setDimensions = dimensions.map((dimension) => ({
            ...dimension,
            aggregationInterval: overrides.aggregationInterval,
        }));
    }
    const startDate = new Date(Date.now() - ONE_DAY_IN_MS);
    const endDate = new Date();

    UsageService.logger.debug(`Gathering Usage for businessID: ${businessID} and customerId: ${customerId}`);
    const aggregateData = await this.influxService.getAggregateUsageForDimension({
        customerId,
        businessID,
        startTime: overrides?.startTime ? overrides?.startTime : startDate.toISOString(),
        endTime: overrides?.endTime ? overrides?.endTime : endDate.toISOString(),
        influxService: this.influxService,
        offeringDocument: { dimensions: setDimensions, ...restOfOfferingDoc },
    });
    return aggregateData;
}

private async findOfferingForCustomer({ customerId, businessID }): Promise<ReadOfferingResponseData> {
    const {
        data: [customer],
    } = await this.customerService.findOne({ customerId, businessID });
    return customer?.offering ? customer.offering : null;
}

