import { OfferingService } from '../offering/offering.service';
import { ReadOfferingResponseData } from '../offering/dto/readOffering.dto';

/**
 * Returns the usage of every dimension of the offering attached to the customer.
 * A customer without an offering cannot be measured, the request is rejected as a conflict.
 */
async findUsageForCustomer({ customerId, businessID }, overrides: QueryParamUsageDto): Promise<ReadUsageData> {
    CustomerService.logger.log('Getting Usage for a customer', { businessID, customerId });
    const {
        data: [customer],
    } = await this.findOne({ customerId, businessID });
    if (!customer?.offering) {
        throw new ConflictException(
            `Customer with ID: ${customerId} has no offering attached, attach an offering to the customer before reading usage`
        );
    }
    const usageDoc = await this.usageService.findUsageForCustomer(
        { customerId, businessID, offering: customer.offering },
        overrides
    );
    if (usageDoc.length > 0) {
        return { data: usageDoc, message: 'Found usage' };
    } else {
        return { data: [], message: 'No Customer usage found' };
    }
}

