import { Test, TestingModule } from '@nestjs/testing';
import { ConflictException } from '@nestjs/common';
import { InfluxService } from '../influx/influx.service';
import { CustomerService } from './customer.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { OfferingService } from '../offering/offering.service';
import { UsageService } from '../usage/usage.service';
import { CustomerEntity } from './entities/customer.entity';
import { paymentChannel, TaxExempt } from './dto/create-customer.dto';

const OFFERING_ID = 'e2f0a2a7-6a1b-4d2d-8a4e-8b1f0f2c9d33';
const CUSTOMER_ID = 'e345f409-daca-4144-91d2-0a0f87c96581';

const buildPoint = () => {
    const tags: Record<string, string> = {};
    return {
        tags,
        tag: (key: string, value: string) => {
            tags[key] = value;
        },
        stringField: jest.fn(),
    };
};

const customerDbModel = (offeringId?: string) => ({
    _measurement: CustomerEntity._measurement,
    _value: 'myCoolCustomer',
    customerId: CUSTOMER_ID,
    paymentChannel: paymentChannel.Stripe,
    email: 'customer@enterprise.tech',
    customerVatId: 'GB VAT 123456789',
    taxExempt: TaxExempt.none,
    offeringId,
});

describe('CustomerService', () => {
    let service: CustomerService;
    const mockLoadPoints = jest.fn();
    const mockGetLatestCustomer = jest.fn(() => [customerDbModel(OFFERING_ID)]);
    const mockGetLatestCustomers = jest.fn(() => [customerDbModel(OFFERING_ID)]);
    const mockGetInvoicesForCustomer = jest.fn(() => []);
    const mockGetAllCustomersWithOfferingId = jest.fn(() => [customerDbModel(OFFERING_ID)]);
    const mockOffering = {
        offeringId: OFFERING_ID,
        offeringName: 'myCoolOffering',
        dimensions: [{ dimensionId: 'dimension-1' }],
    };
    const mockOfferingFindOne = jest.fn(() => ({ data: [mockOffering], message: 'Found Offering' }));
    const mockFindUsageForCustomer = jest.fn(() => [{ dimensionId: 'dimension-1', usage: [{ value: '1' }] }]);
    const mockSchedulerCreate = jest.fn();
    const mockSchedulerRemove = jest.fn();

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => buildPoint(),
                        getLatestCustomer: mockGetLatestCustomer,
                        getLatestCustomers: mockGetLatestCustomers,
                        getInvoicesForCustomer: mockGetInvoicesForCustomer,
                        getAllCustomersWithOfferingId: mockGetAllCustomersWithOfferingId,
                    };
                }
                if (token === SchedulerService) {
                    return { create: mockSchedulerCreate, remove: mockSchedulerRemove };
                }
                if (token === OfferingService) {
                    return { findOne: mockOfferingFindOne };
                }
                if (token === UsageService) {
                    return { findUsageForCustomer: mockFindUsageForCustomer };
                }
            })
            .compile();

        service = module.get<CustomerService>(CustomerService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('should persist the offeringId of a customer', async () => {
        await service.create(
            { customerName: 'myCoolCustomer', email: '', paymentChannel: paymentChannel.Stripe, offeringId: OFFERING_ID },
            'subject'
        );
        expect(mockOfferingFindOne).toBeCalledTimes(1);
        const [[, , points]] = mockLoadPoints.mock.calls as any;
        expect(points[0].tags.offeringId).toEqual(OFFERING_ID);
    });

    it('should return the offeringId and the hydrated offering when reading a customer', async () => {
        const {
            data: [customer],
        } = await service.findOne({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp' });
        expect(customer.offeringId).toEqual(OFFERING_ID);
        expect(customer.offering).toEqual(mockOffering);
        expect(mockOfferingFindOne).toBeCalledWith({ businessID: 'myCoolCorp', offeringId: OFFERING_ID });
    });

    it('should return the hydrated offering for every customer', async () => {
        const { data } = await service.findAll({ businessID: 'myCoolCorp' });
        expect(data[0].offeringId).toEqual(OFFERING_ID);
        expect(data[0].offering).toEqual(mockOffering);
    });

    it('should find every customer attached to an offering', async () => {
        const { data } = await service.findAllCustomersWithOfferingId({
            businessID: 'myCoolCorp',
            offeringId: OFFERING_ID,
        });
        expect(mockGetAllCustomersWithOfferingId).toBeCalledWith({
            businessID: 'myCoolCorp',
            offeringId: OFFERING_ID,
        });
        expect(data[0].customerId).toEqual(CUSTOMER_ID);
    });

    it('should delete a customer without looking at legacy service records', async () => {
        const { message } = await service.remove({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp' });
        expect(message).toEqual('Deleted Customer');
        expect(mockLoadPoints).toBeCalledTimes(1);
    });

    it('should return the usage of the offering attached to the customer', async () => {
        const { data } = await service.findUsageForCustomer(
            { customerId: CUSTOMER_ID, businessID: 'myCoolCorp' },
            { startTime: '2023-01-01T00:00:00Z', endTime: '2023-01-02T00:00:00Z' }
        );
        expect(mockFindUsageForCustomer).toBeCalledWith(
            { customerId: CUSTOMER_ID, businessID: 'myCoolCorp', offering: mockOffering },
            { startTime: '2023-01-01T00:00:00Z', endTime: '2023-01-02T00:00:00Z' }
        );
        expect(data).toEqual([{ dimensionId: 'dimension-1', usage: [{ value: '1' }] }]);
    });

    it('should reject usage of a customer without an offering as a conflict', async () => {
        mockGetLatestCustomer.mockImplementationOnce(() => [customerDbModel(undefined)]);
        await expect(
            service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp' }, {})
        ).rejects.toThrow(ConflictException);
        expect(mockFindUsageForCustomer).not.toBeCalled();
    });
});

import { Test, TestingModule } from '@nestjs/testing';
