const CUSTOMER_ID = 'e345f409-daca-4144-91d2-0a0f87c96581';
const OFFERING_ID = 'e2f0a2a7-6a1b-4d2d-8a4e-8b1f0f2c9d33';

describe('UsageService', () => {
    let service: UsageService;
    const offering = {
        offeringId: OFFERING_ID,
        offeringName: 'myCoolOffering',
        dimensions: [{ dimensionId: 'dimension-1', aggregationInterval: aggregationInterval.hour }],
    };
    const mockGetAggregateUsageForDimension = jest.fn(() => [{ dimensionId: 'dimension-1', usage: [] }]);
    const mockCustomerFindOne = jest.fn(() => ({
        data: [{ customerId: CUSTOMER_ID, offeringId: OFFERING_ID, offering }],
        message: 'Found Customer',
    }));

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({
            providers: [UsageService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return { getAggregateUsageForDimension: mockGetAggregateUsageForDimension };
                }
                if (token === CustomerService) {
                    return { findOne: mockCustomerFindOne };
                }
                if (token === MeasurementConfigService || token === DimensionsService || token === OfferingService) {
                    return {};
                }
            })
            .compile();

        service = module.get<UsageService>(UsageService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    it('should aggregate the usage of the dimensions of the customer offering with the customerId', async () => {
        await service.findUsageForCustomer(
            { customerId: CUSTOMER_ID, businessID: 'myCoolCorp' },
            { startTime: '2023-01-01T00:00:00Z', endTime: '2023-01-02T00:00:00Z' }
        );
        expect(mockCustomerFindOne).toBeCalledWith({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp' });
        expect(mockGetAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                customerId: CUSTOMER_ID,
                businessID: 'myCoolCorp',
                startTime: '2023-01-01T00:00:00Z',
                endTime: '2023-01-02T00:00:00Z',
                offeringDocument: expect.objectContaining({ dimensions: offering.dimensions }),
            })
        );
    });

    it('should override the aggregation interval of every dimension', async () => {
        await service.findUsageForCustomer(
            { customerId: CUSTOMER_ID, businessID: 'myCoolCorp' },
            { aggregationInterval: aggregationInterval.none }
        );
        const [[{ offeringDocument }]] = mockGetAggregateUsageForDimension.mock.calls as any;
        expect(offeringDocument.dimensions).toEqual([
            { dimensionId: 'dimension-1', aggregationInterval: aggregationInterval.none },
        ]);
    });

    it('should not resolve the customer when the offering is passed in', async () => {
        await service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp', offering } as any, {});
        expect(mockCustomerFindOne).not.toBeCalled();
        expect(mockGetAggregateUsageForDimension).toBeCalledTimes(1);
    });

    it('should reject a usage read for a customer without an offering as a conflict', async () => {
        mockCustomerFindOne.mockImplementationOnce(
            () => ({ data: [{ customerId: CUSTOMER_ID } as any], message: 'Found Customer' } as any)
        );
        await expect(service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: 'myCoolCorp' }, {})).rejects.toThrow(
            ConflictException
        );
        expect(mockGetAggregateUsageForDimension).not.toBeCalled();
    });
});

