export const deleteAllServices = async (): Promise<void> => {
    const services: Service[] = [];
    const serviceClient = new Service();
    const response = await serviceClient.getAll();
    response.forEach((serviceMetadata) => {
        services.push(new Service(serviceMetadata.serviceName, serviceMetadata.serviceId));
    });

    await Promise.all(
        services.map(async (service) => {
            try {
                const res = await service.delete();
                return res;
            } catch (e) {
                console.debug(e);
            }
        })
    );
    await sleep(1000 * 2);
    expect((await serviceClient.getAll()).length).toBe(0);
};

